const fs = require('fs');

const filename = process.argv[2];
const buffer = fs.readFileSync(filename);

// Parse ELF header
const is64 = buffer[4] === 2;
const littleEndian = buffer[5] === 1;

function readU16(offset) {
  return littleEndian ? buffer.readUInt16LE(offset) : buffer.readUInt16BE(offset);
}
function readU32(offset) {
  return littleEndian ? buffer.readUInt32LE(offset) : buffer.readUInt32BE(offset);
}
function readU64(offset) {
  const low = readU32(offset);
  const high = readU32(offset + 4);
  return high * 0x100000000 + low;
}

let shoff, shentsize, shnum, shstrndx;
if (is64) {
  shoff = Number(readU64(0x28));
  shentsize = readU16(0x3a);
  shnum = readU16(0x3c);
  shstrndx = readU16(0x3e);
} else {
  shoff = readU32(0x20);
  shentsize = readU16(0x2e);
  shnum = readU16(0x30);
  shstrndx = readU16(0x32);
}

const memory = {};

for (let i = 0; i < shnum; i++) {
  const shOffset = shoff + i * shentsize;
  const type = readU32(shOffset + 4);
  const flags = is64 ? readU64(shOffset + 8) : readU32(shOffset + 8);
  const addr = is64 ? readU64(shOffset + 16) : readU32(shOffset + 12);
  const fileOffset = is64 ? readU64(shOffset + 24) : readU32(shOffset + 16);
  const size = is64 ? readU64(shOffset + 32) : readU32(shOffset + 20);

  // Check ALLOC flag (SHF_ALLOC = 0x2)
  if ((flags & 0x2) !== 0 && type !== 8) { // Not NOBITS (BSS can be 0 or omitted, but let's check PROGBITS)
    if (type === 1 && size > 0) { // SHT_PROGBITS
      for (let offset = 0; offset < size; offset += 4) {
        if (fileOffset + offset + 4 <= buffer.length) {
          const val = littleEndian ? buffer.readInt32LE(fileOffset + offset) : buffer.readInt32BE(fileOffset + offset);
          const vaddr = Number(addr) + offset;
          memory[vaddr.toString()] = val;
        }
      }
    }
  }
}

